describe('Icon Button Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have accessible names for all icon buttons', () => {
        cy.get('button[aria-label]').each(($button) => {
            const label = $button.attr('aria-label');
            expect(label).to.exist;
            expect(label).to.not.be.empty;
        });
    });

    it('should not have any icon buttons without accessible names', () => {
        cy.get('button:not([aria-label])').should('have.length', 0);
    });
});
